(require '[otehon.ipld-forest :as catalog] '[otehon.storage :as store] '[otehon.forest-writer :as writer]
         '[kotobase.engine.prolly :as prolly] '[kotobase.engine.contract :as eng] '[kotobase-peer.policy :as policy]
         '[datom.source :as source] '[datalog.core :as datalog] '[dango.chain :as chain] '[ed25519.sign :as ed]
         '[kotobase.governed-execution :as governed] '[kotobase.execution-identity :as id]
         '[kotobase.execution-keys :as keys] '[kotoba.value.codec :as codec])
(import '[java.security MessageDigest] '[java.util HexFormat])
(def data-dir (or (System/getenv "GROUP_FOREST_STORE") ".agent-output/ipld-writer-v3/store"))
(def output-dir (or (System/getenv "RECEIPT_OUTPUT") ".agent-output/receipt"))
(def receipt-dir (str output-dir "/store"))
(def staging (str output-dir "/stage"))
(def tool (or (System/getenv "FOREST_TOOL") (throw (ex-info "FOREST_TOOL required" {}))))
(def h (catalog/recover-group data-dir "test"))
(def basis (get-in h [:group :basis-cid]))
(defn sha [s] (.formatHex (HexFormat/of) (.digest (MessageDigest/getInstance "SHA-256") (.getBytes (str s) "UTF-8"))))
(def engine (prolly/prolly-engine {:put! (fn [& _] (throw (ex-info "read only" {}))) :get-fn #(catalog/get-group-block h %)
 :blind-fn #(str "blind-fixture:" %) :encrypt-fn identity :decrypt-fn identity :digest-fn sha}))
(def snap (eng/open-snapshot engine (eng/restore-state engine basis)))
(def p (policy/policy-of (mapv (fn [{:keys [e a v]}] {:e e :a (str a) :v_edn (pr-str v)}) (eng/scan engine snap ["kotobase.policy/read" nil nil]))))
(def pcid (policy/policy-cid p))
(def resource (str "kotoba://basis/" basis))
(def seed (vec (repeat 32 1)))
(def token (chain/root {:issuer-seed seed :grant {:caps #{[:datom/read-protected resource]} :before 1800000000} :caveats [] :next-seed (vec (repeat 32 2))}))
(def decision (chain/verify (chain/present token) {:roots #{(ed/public-key seed)} :request {:req/kind :datom/read-protected :req/resource resource :req/now 1700000000}}))
(def query {:find [:file/root :chunk/cid] :where [[:query/id "forest-join-v1"]] :scope {:tenant "test" :resources #{resource} :purpose :audit :basis basis} :limit 10})
(def request {:request/version 1 :principal "did:key:fixture" :tenant "test" :graph "forest" :operation :read :query/digest (id/value-cid query) :base/commit basis :authority/policy pcid :authority/epoch 7 :nonce "fixture-1" :expires-at "2026-09-02T15:00:00Z"})
(def issuer (vec (repeat 32 3)))
(def executor (vec (repeat 32 4)))
(defn payload-bytes [s] (mapv #(bit-and 255 %) (.getBytes s "UTF-8")))
(defn sign [which s record] {:key/id which :key/algorithm :ed25519 :signature/value (ed/sign (ed/secret-key! s) (payload-bytes (id/payload-cid record)))})
(def manifest (let [m {:execution/version 1 :data/commit basis :authority/policy pcid :authority/epoch 7 :location/manifest "fixture-location" :schema/root "fixture-schema" :parent nil :issued-at "2026-09-02T14:00:00Z"}] (assoc m :signature (sign "issuer" issuer m))))
(def verifier (keys/verifier {:registry (keys/static-registry {{:role :issuer :tenant "test" :epoch 7} [{:key/id "issuer" :key/algorithm :ed25519 :key/material (ed/public-key issuer)}] {:role :executor :tenant "test" :epoch 7} [{:key/id "executor" :key/algorithm :ed25519 :key/material (ed/public-key executor)}]}) :verify-with (fn [{:keys [key payload-cid signature-value]}] (ed/verify (:key/material key) (payload-bytes payload-cid) signature-value))}))
(def dq '{:find [?root ?cid] :where [["file" :file/root ?root] ["file" :file/chunk ?c] [?c :chunk/index 8] [?c :chunk/cid ?cid]]})
(defn evaluate [q _] (assert (= q query)) (let [src (reify source/IPatternSource (-scan [_ pattern] (mapv (fn [{:keys [e a v]}] {:s e :p a :o v}) (eng/scan engine snap pattern)))) visible (policy/visible-for p #{policy/read-protected-capability})] (mapv (fn [[root cid]] {:file/root root :chunk/cid cid}) (datalog/q src dq #(visible (update % :p str))))))
(defn block [x] {:cid (id/value-cid x) :bytes (byte-array (map unchecked-byte (codec/encode-value x)))})
(defn commit! [receipt] (let [b (mapv block [receipt request manifest]) cid (:cid (first b))]
 (writer/put-ipld-blocks! receipt-dir "receipt" cid b staging tool)
 (let [recovered (catalog/recover-group receipt-dir "receipt")]
  (doseq [{:keys [cid bytes]} b] (assert (= (vec bytes) (vec (catalog/get-group-block recovered cid)))))
  {:receipt/durable? true :receipt/cid cid})))
(def opts {:request request :manifest manifest :authority {:now "2026-09-02T14:30:00Z" :epoch 7 :consume-nonce! (fn [_] true)} :value-cid id/value-cid :verify verifier :plan-digest (fn [x] (id/value-cid (if x "fixture-plan" "no-plan"))) :cost (fn [] {:dependent-hops 0 :requests 0 :bytes 0 :cache-profile :unknown}) :implementation/build "hosted-reference-fixture" :sign #(sign "executor" executor %) :commit! commit! :authorize! (fn [q] {:allowed? (:dango/allowed? decision) :projection (set (:find q)) :basis basis :policy-cid pcid}) :schema {:file/root {:class :public} :chunk/cid {:class :internal}} :grant {:granted #{:public :internal} :scopes #{}} :query query :evaluate! evaluate})
(store/init! receipt-dir)
(def result (governed/execute! opts))
(assert (= [{:file/root "bafyreidqkmghsd65dwq22umpkrqecyamfhevsbq7xemjfe7tb6wnhvxsny" :chunk/cid "bafkreidxq3azg4pwxcuurzkrmjha3uuzhstmefbzx6dw6z5bjaqya64mra"}] (:rows result)))
(prn {:rows (:rows result) :receipt (get-in result [:provenance :receipt-cid]) :basis basis :pass true})
(spit (str output-dir "/ids.edn") (pr-str {:receipt (get-in result [:provenance :receipt-cid]) :request (id/value-cid request) :manifest (id/value-cid manifest) :result (id/value-cid (:rows result))}))
(shutdown-agents)
